public final class ScheduledTasksPanel extends JPanel {
    private record Frequency(String label,int minutes){@Override public String toString(){return tr(label);}}
    private static final Frequency ONCE=new Frequency("Una vez",0),HOURLY=new Frequency("Cada hora",60),DAILY=new Frequency("Diario",1440),WEEKLY=new Frequency("Semanal",10080),CUSTOM=new Frequency("Personalizado",-1);
    private final ScheduledTasks engine;private final Supplier<List<ConnectionProfile>> profiles;private final Function<String,JdbcSession> activeSessions;private final String defaultProfile,database;
    private final ExternalTaskScheduler external;private final JLabel runnerStatus=new JLabel(tr("Comprobando ejecutor externo…"));private JButton installRunner,removeRunner,runRunner;
    private List<ScheduledTasks.Task> tasks=List.of();private final DefaultTableModel model=new DefaultTableModel(new Object[]{tr("Nombre"),tr("Tipo"),tr("Base"),tr("Activa"),tr("Próxima ejecución"),tr("Último resultado"),tr("Archivos")},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);
    private final javax.swing.Timer timer=new javax.swing.Timer(2000,e->refresh());
    public ScheduledTasksPanel(ScheduledTasks engine,Supplier<List<ConnectionProfile>> profiles,String defaultProfile,String database){this(engine,profiles,defaultProfile,database,ExternalTaskScheduler.configured(),id->null);}
    public ScheduledTasksPanel(ScheduledTasks engine,Supplier<List<ConnectionProfile>> profiles,String defaultProfile,String database,Function<String,JdbcSession> activeSessions){this(engine,profiles,defaultProfile,database,ExternalTaskScheduler.configured(),activeSessions);}
    ScheduledTasksPanel(ScheduledTasks engine,Supplier<List<ConnectionProfile>> profiles,String defaultProfile,String database,ExternalTaskScheduler external){this(engine,profiles,defaultProfile,database,external,id->null);}
    ScheduledTasksPanel(ScheduledTasks engine,Supplier<List<ConnectionProfile>> profiles,String defaultProfile,String database,ExternalTaskScheduler external,Function<String,JdbcSession> activeSessions){super(new BorderLayout(8,8));this.engine=engine;this.profiles=profiles;this.activeSessions=activeSessions;this.defaultProfile=defaultProfile;this.database=database;this.external=external;setBorder(new javax.swing.border.EmptyBorder(12,12,12,12));
        JPanel top=new JPanel(new BorderLayout(6,8));JPanel notices=new JPanel(new GridLayout(0,1,2,2));notices.add(new JLabel(tr("Las tareas se ejecutan dentro de AdisDB; el ejecutor externo permite continuarlas con la aplicación cerrada y la sesión de Windows iniciada.")));notices.add(runnerStatus);top.add(notices,BorderLayout.NORTH);JToolBar bar=new JToolBar();bar.setFloatable(false);
        addAction(bar,"Nuevo reporte",()->edit(null,ScheduledTasks.Kind.REPORT));addAction(bar,"Nuevo respaldo",()->edit(null,ScheduledTasks.Kind.BACKUP));addAction(bar,"Nuevo script SQL",()->edit(null,ScheduledTasks.Kind.SQL));bar.addSeparator();addAction(bar,"Editar",()->{var task=selected();if(task!=null)edit(task,task.kind());});addAction(bar,"Ejecutar ahora",()->{var task=selected();if(task!=null&&JOptionPane.showConfirmDialog(this,task.name()+"\n"+task.database()+"\n"+tr("¿Ejecutar esta tarea ahora?"),tr("Tareas programadas"),JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){engine.runNow(task.id());refresh();}});addAction(bar,"Activar / pausar",()->{var task=selected();if(task!=null)try{engine.enable(task.id(),!task.enabled());refresh();}catch(Exception error){error(error);}});addAction(bar,"Cancelar",()->{var task=selected();if(task!=null)engine.cancel(task.id());});addAction(bar,"Eliminar",()->{var task=selected();if(task!=null&&JOptionPane.showConfirmDialog(this,tr("¿Eliminar la tarea?")+"\n"+task.name(),tr("Tareas programadas"),JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{engine.delete(task.id());refresh();}catch(Exception error){error(error);}});bar.addSeparator();addAction(bar,"Verificar respaldo…",this::verifyBackup);bar.addSeparator();installRunner=addAction(bar,"Activar ejecutor externo",()->externalAction(0));removeRunner=addAction(bar,"Desactivar ejecutor externo",()->externalAction(1));runRunner=addAction(bar,"Comprobar ahora",()->externalAction(2));top.add(bar,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);table.setAutoCreateRowSorter(true);table.setRowHeight(28);add(new JScrollPane(table));add(new JLabel(tr("Cada respaldo programado incluye un manifiesto SHA-256 y conserva la cantidad configurada de versiones anteriores.")),BorderLayout.SOUTH);refresh();refreshExternal();
    }
    public void addNotify(){super.addNotify();timer.start();}public void removeNotify(){timer.stop();super.removeNotify();}
    public void create(ScheduledTasks.Kind kind){edit(null,kind);}
    private JButton addAction(JToolBar bar,String text,Runnable action){JButton button=UiLanguage.text(new JButton(tr(text)),UiLanguage.key(text));button.addActionListener(e->{if(Set.of("Activar / pausar","Cancelar").contains(text)){var task=selected();if(task==null||!Confirmations.ask(this,text,task.name()+" · "+task.database()+"\n"+tr("¿Aplicar esta acción a la tarea seleccionada?")))return;}action.run();});bar.add(button);return button;}
    private ScheduledTasks.Task selected(){int row=table.getSelectedRow();return row<0?null:tasks.get(table.convertRowIndexToModel(row));}
    private void refresh(){var before=selected();engine.reload();tasks=engine.list();model.setRowCount(0);for(var task:tasks){var state=engine.state(task.id());model.addRow(new Object[]{task.name(),tr(kind(task.kind())),task.database(),state.running()?tr("Ejecutando…"):tr(task.enabled()?"Sí":"No"),java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm").withZone(ZoneId.systemDefault()).format(task.next()),tr(state.status()),state.output()});}if(before!=null)for(int i=0;i<tasks.size();i++)if(tasks.get(i).id().equals(before.id())){int row=table.convertRowIndexToView(i);table.setRowSelectionInterval(row,row);}}
    private static String kind(ScheduledTasks.Kind kind){return switch(kind){case BACKUP->"Respaldo SQL";case REPORT->"Reporte SQL";case SQL->"Script SQL";};}
    private void edit(ScheduledTasks.Task previous,ScheduledTasks.Kind kind){
        if(previous!=null&&engine.state(previous.id()).running()){error(new IllegalStateException(tr("Espera a que termine la tarea.")));return;}List<ConnectionProfile> available=profiles.get();if(available.isEmpty()){error(new IllegalStateException(tr("Crea una conexión antes de programar tareas.")));return;}
        JComboBox<ConnectionProfile> connection=new JComboBox<>(available.toArray(ConnectionProfile[]::new));String profile=previous==null?defaultProfile:previous.profile();for(var p:available)if(p.id().equals(profile))connection.setSelectedItem(p);
        String initialDatabase=previous==null?database:previous.database();JTextField name=new JTextField(previous==null?tr(kind(kind)):previous.name());JComboBox<String> base=new JComboBox<>();base.setEditable(true);if(initialDatabase!=null&&!initialDatabase.isBlank())base.addItem(initialDatabase);base.setSelectedItem(initialDatabase);JTextField script=new JTextField(previous==null?"":previous.script()),output=new JTextField(previous==null?Path.of(System.getProperty("user.home"),"AdisDB-Reports").toString():previous.output());JPasswordField password=new JPasswordField();JSpinner retention=new JSpinner(new SpinnerNumberModel(previous==null?7:previous.retention(),0,1000,1));
        JSpinner start=new JSpinner(new SpinnerDateModel(Date.from(previous==null?Instant.now().plusSeconds(60):previous.next()),null,null,Calendar.MINUTE));start.setEditor(new JSpinner.DateEditor(start,"yyyy-MM-dd HH:mm"));int previousMinutes=previous==null?1440:previous.minutes();JSpinner minutes=new JSpinner(new SpinnerNumberModel(previousMinutes,0,525600,1));JComboBox<Frequency> frequency=new JComboBox<>(new Frequency[]{ONCE,HOURLY,DAILY,WEEKLY,CUSTOM});Frequency selectedFrequency=frequency(previousMinutes);frequency.setSelectedItem(selectedFrequency);minutes.setEnabled(selectedFrequency==CUSTOM);frequency.addActionListener(e->minutes.setEnabled(frequency.getSelectedItem()==CUSTOM));JCheckBox authorized=new JCheckBox(tr("Autorizo la ejecución automática de este script SQL en la conexión y base indicadas."));
        JButton reloadDatabases=new JButton(tr("Actualizar bases"));JLabel databaseStatus=new JLabel(" ");databaseStatus.setFont(databaseStatus.getFont().deriveFont(databaseStatus.getFont().getSize2D()-1f));JPanel databaseField=new JPanel(new BorderLayout(6,2));databaseField.add(base,BorderLayout.CENTER);databaseField.add(reloadDatabases,BorderLayout.EAST);databaseField.add(databaseStatus,BorderLayout.SOUTH);long[] catalogRequest={0};reloadDatabases.addActionListener(e->loadDatabases(connection,base,password,reloadDatabases,databaseStatus,catalogRequest,true));connection.addActionListener(e->{ConnectionProfile value=(ConnectionProfile)connection.getSelectedItem();if(value!=null){base.setSelectedItem(value.database());loadDatabases(connection,base,password,reloadDatabases,databaseStatus,catalogRequest,false);}});
        JPanel form=new JPanel(new GridBagLayout());GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,5,5,5);g.fill=GridBagConstraints.HORIZONTAL;int row=0;field(form,g,row++,"Nombre:",name);field(form,g,row++,"Conexión:",connection);field(form,g,row++,"Base:",databaseField);
        if(kind!=ScheduledTasks.Kind.BACKUP){JPanel file=new JPanel(new BorderLayout(6,0));file.add(script);JButton browse=new JButton("…");browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("SQL","sql"));if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)script.setText(chooser.getSelectedFile().toString());});file.add(browse,BorderLayout.EAST);field(form,g,row++,"Archivo SQL:",file);}
        JPanel folder=new JPanel(new BorderLayout(6,0));folder.add(output);JButton browse=new JButton("…");browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)output.setText(chooser.getSelectedFile().toString());});folder.add(browse,BorderLayout.EAST);field(form,g,row++,"Carpeta de salida:",folder);if(kind==ScheduledTasks.Kind.BACKUP)field(form,g,row++,"Respaldos a conservar (0 = todos):",retention);field(form,g,row++,"Primera ejecución:",start);field(form,g,row++,"Frecuencia:",frequency);field(form,g,row++,"Intervalo personalizado (minutos):",minutes);field(form,g,row++,"Contraseña (solo esta sesión):",password);
        g.gridx=0;g.gridy=row++;g.gridwidth=2;form.add(new JLabel(tr("En Windows también puede utilizarse la contraseña cifrada guardada en el perfil.")),g);if(kind==ScheduledTasks.Kind.SQL){g.gridy=row++;form.add(authorized,g);g.gridy=row++;form.add(new JLabel(tr("Los cambios DDL pueden permanecer si una sentencia posterior falla.")),g);}form.setPreferredSize(new Dimension(830,kind==ScheduledTasks.Kind.SQL?500:430));loadDatabases(connection,base,password,reloadDatabases,databaseStatus,catalogRequest,false);
        if(JOptionPane.showConfirmDialog(this,form,tr("Programar tarea: ")+tr(kind(kind)),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;ConnectionProfile selected=(ConnectionProfile)connection.getSelectedItem();char[] secret=password.getPassword();
        if(kind==ScheduledTasks.Kind.SQL&&(!authorized.isSelected()||selected.readOnly())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("Autoriza el script y utiliza una conexión habilitada para escritura.")));return;}if(kind==ScheduledTasks.Kind.BACKUP&&!SqlBackupService.supported(selected.type())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("El respaldo SQL requiere MySQL o MariaDB.")));return;}
        String title=name.getText().trim(),target=Objects.toString(base.getEditor().getItem(),"").trim(),source=script.getText().trim(),destination=output.getText().trim();Instant date=((Date)start.getValue()).toInstant();Frequency selectedSchedule=(Frequency)frequency.getSelectedItem();int frequencyMinutes=selectedSchedule==CUSTOM?((Number)minutes.getValue()).intValue():selectedSchedule.minutes();
        new SwingWorker<SqlImportService.Analysis,Void>(){protected SqlImportService.Analysis doInBackground()throws Exception{return kind==ScheduledTasks.Kind.BACKUP?null:SqlImportService.analyze(Path.of(source),new SqlTransferControl());}protected void done(){try{var analysis=get();if(analysis!=null){JTextArea text=new JTextArea(selected.name()+" · "+selected.host()+":"+selected.port()+" · "+target+"\n"+analysis.statements()+" "+tr("sentencias")+" · "+analysis.destructive()+" "+tr("modifican o eliminan objetos/datos")+"\n\n"+analysis.preview(),15,80);text.setEditable(false);text.setCaretPosition(0);if(JOptionPane.showConfirmDialog(ScheduledTasksPanel.this,new JScrollPane(text),tr("Revisar el archivo antes de programar"),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;}
            if(!LicenseGate.ensure(ScheduledTasksPanel.this)||!Confirmations.ask(ScheduledTasksPanel.this,"Guardar tarea programada",title+"\n"+selected.name()+" · "+target+"\n"+date.atZone(ZoneId.systemDefault())+"\n"+tr("Se ejecutará automáticamente con las opciones revisadas; el ejecutor externo puede continuar con AdisDB cerrado. ¿Programar?")))return;
            ScheduledTasks.Task task=new ScheduledTasks.Task(previous==null?UUID.randomUUID().toString():previous.id(),title,selected.id(),target,kind,analysis==null?"":analysis.file().toString(),analysis==null?"":analysis.sha256(),Path.of(destination).toAbsolutePath().toString(),frequencyMinutes,date,true,kind==ScheduledTasks.Kind.BACKUP?((Number)retention.getValue()).intValue():0);engine.put(task);if(secret.length>0)engine.credentials(selected.id(),secret);refresh();
        }catch(Exception failure){error(failure.getCause()==null?failure:failure.getCause());}finally{Arrays.fill(secret,'\0');}}}.execute();
    }
    private static Frequency frequency(int minutes){for(Frequency value:new Frequency[]{ONCE,HOURLY,DAILY,WEEKLY})if(value.minutes()==minutes)return value;return CUSTOM;}
    private void loadDatabases(JComboBox<ConnectionProfile> connection,JComboBox<String> base,JPasswordField password,JButton reload,JLabel status,long[] generation,boolean reportFailure){ConnectionProfile profile=(ConnectionProfile)connection.getSelectedItem();if(profile==null)return;long request=++generation[0];String current=Objects.toString(base.getEditor().getItem(),"").trim();char[] typed=password.getPassword();reload.setEnabled(false);status.setText(tr("Cargando bases disponibles…"));new SwingWorker<List<String>,Void>(){protected List<String> doInBackground()throws Exception{JdbcSession active=activeSessions.apply(profile.id());if(active!=null&&active.isOpen())try(JdbcSession.ReadLease read=active.borrowReadOnly(10_000)){return databaseNames(profile,read.session().connection());}char[] secret=typed.length>0?typed:engine.credentials(profile.id());try(JdbcSession session=JdbcSession.open(profile,secret)){return databaseNames(profile,session.connection());}finally{Arrays.fill(secret,'\0');}}protected void done(){if(request!=generation[0])return;reload.setEnabled(true);try{List<String> names=get();DefaultComboBoxModel<String> model=new DefaultComboBoxModel<>(names.toArray(String[]::new));base.setModel(model);base.setEditable(true);String choice=contains(names,current)?current:contains(names,profile.database())?profile.database():names.isEmpty()?current:names.get(0);if(choice!=null&&!choice.isBlank()){if(!contains(names,choice))base.addItem(choice);base.setSelectedItem(choice);}status.setText(names.isEmpty()?tr("No se encontraron bases; puedes escribir el nombre."):names.size()+" "+tr("bases disponibles"));}catch(Exception failure){Throwable cause=failure;while(cause.getCause()!=null)cause=cause.getCause();status.setText(tr("No se pudo cargar la lista; puedes escribir la base."));if(reportFailure)error(cause);}}}.execute();}
    static List<String> databaseNames(ConnectionProfile profile,Connection connection)throws SQLException{Set<String> names=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);DatabaseMetaData metadata=connection.getMetaData();if(profile.type()==DatabaseType.POSTGRESQL){add(names,profile.database());return List.copyOf(names);}if(profile.type()==DatabaseType.ORACLE){try(ResultSet rows=metadata.getSchemas()){while(rows.next())add(names,rows.getString("TABLE_SCHEM"));}}else{try(ResultSet rows=metadata.getCatalogs()){while(rows.next())add(names,rows.getString("TABLE_CAT"));}if(names.isEmpty())try(ResultSet rows=metadata.getSchemas()){while(rows.next())add(names,rows.getString("TABLE_SCHEM"));}}add(names,profile.database());return List.copyOf(names);}
    private static void add(Set<String> target,String value){if(value!=null&&!value.isBlank())target.add(value);}
    private static boolean contains(Collection<String> values,String expected){if(expected==null)return false;for(String value:values)if(value.equalsIgnoreCase(expected))return true;return false;}
    private static void field(JPanel form,GridBagConstraints g,int row,String caption,JComponent input){g.gridwidth=1;g.gridy=row;g.gridx=0;g.weightx=0;form.add(new JLabel(tr(caption)),g);g.gridx=1;g.weightx=1;form.add(input,g);}
    private void refreshExternal(){new SwingWorker<ExternalTaskScheduler.Status,Void>(){protected ExternalTaskScheduler.Status doInBackground(){return external.status();}protected void done(){try{var value=get();runnerStatus.setText(tr(value.detail()));installRunner.setEnabled(value.supported()&&!value.installed());removeRunner.setEnabled(value.supported()&&value.installed());runRunner.setEnabled(value.supported()&&value.installed());}catch(Exception failure){runnerStatus.setText(tr("No se pudo comprobar el ejecutor externo."));installRunner.setEnabled(false);removeRunner.setEnabled(false);runRunner.setEnabled(false);}}}.execute();}
    private void externalAction(int action){if(action!=1&&!LicenseGate.ensure(this))return;String question=action==0?tr("Windows comprobará las tareas cada 5 minutos con tu misma cuenta, sin guardar contraseñas en el comando. ¿Activar?"):action==1?tr("Las tareas volverán a ejecutarse solamente cuando AdisDB esté abierto. ¿Desactivar?"):tr("¿Pedir a Windows que compruebe ahora las tareas vencidas?");if(JOptionPane.showConfirmDialog(this,question,tr("Ejecutor externo"),JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;installRunner.setEnabled(false);removeRunner.setEnabled(false);runRunner.setEnabled(false);new SwingWorker<ExternalTaskScheduler.Result,Void>(){protected ExternalTaskScheduler.Result doInBackground()throws Exception{return action==0?external.install():action==1?external.uninstall():external.runNow();}protected void done(){try{get();JOptionPane.showMessageDialog(ScheduledTasksPanel.this,tr(action==0?"Ejecutor externo activado.":action==1?"Ejecutor externo desactivado.":"Comprobación iniciada."));}catch(Exception failure){Throwable cause=failure;while(cause.getCause()!=null)cause=cause.getCause();error(cause);}finally{refreshExternal();}}}.execute();}
    private void verifyBackup(){JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Respaldo SQL AdisDB","sql"));if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;Path selected=chooser.getSelectedFile().toPath();new SwingWorker<BackupCatalog.Verification,Void>(){protected BackupCatalog.Verification doInBackground()throws Exception{return BackupCatalog.verify(selected);}protected void done(){try{var value=get();JOptionPane.showMessageDialog(ScheduledTasksPanel.this,value.detail()+"\n"+tr("Base: ")+value.database()+"\nSHA-256: "+value.sha256()+"\n"+tr("Tamaño: ")+value.size(),tr("Verificar respaldo"),value.valid()?JOptionPane.INFORMATION_MESSAGE:JOptionPane.WARNING_MESSAGE);}catch(Exception failure){Throwable cause=failure;while(cause.getCause()!=null)cause=cause.getCause();error(cause);}}}.execute();}
    private void error(Throwable error){JOptionPane.showMessageDialog(this,error.getMessage(),tr("Tareas programadas"),JOptionPane.ERROR_MESSAGE);}
}
